const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const _ = require('lodash');

// In-memory settings store
const settingsStore = {};

const typeDefs = gql`
  type Setting {
    key: String!
    value: String
  }

  input SettingInput {
    path: String!
    value: String!
  }

  input BatchSettingsInput {
    settings: [SettingInput!]!
  }

  type Mutation {
    updateSetting(input: SettingInput!): Setting
    batchUpdateSettings(input: BatchSettingsInput!): [Setting]
  }

  type Query {
    getSetting(key: String!): Setting
    getAllSettings: [Setting]
  }
`;

const resolvers = {
  Query: {
    getSetting: (_, { key }) => {
      return { key, value: settingsStore[key] || null };
    },
    getAllSettings: () => {
      return Object.keys(settingsStore).map(k => ({ key: k, value: settingsStore[k] }));
    }
  },
  Mutation: {
    updateSetting: (_, { input }) => {
      const { path, value } = input;
      // Use lodash set to allow nested path updates like "theme.color"
      _.set(settingsStore, path, value);
      return { key: path, value };
    },
    batchUpdateSettings: (_, { input }) => {
      const results = [];
      for (const setting of input.settings) {
        // Batch processing - each setting applied via lodash set
        _.set(settingsStore, setting.path, setting.value);
        results.push({ key: setting.path, value: setting.value });
      }
      return results;
    }
  }
};

const app = express();

// Basic request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: process.env.NODE_ENV !== 'production',
  formatError: (err) => {
    // Don't expose internal errors in production
    if (process.env.NODE_ENV === 'production') {
      return { message: 'Internal server error' };
    }
    return err;
  }
});

server.applyMiddleware({ app, path: '/graphql' });

const PORT = process.env.PORT || 4000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`GraphQL endpoint: http://localhost:${PORT}/graphql`);
});

module.exports = { app, settingsStore };
